### Python

```python
import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    q = int(next(it))
    out_lines = []
    INF = 10**18

    for _ in range(q):
        n = int(next(it))
        a = [0] + [int(next(it)) for _ in range(n)]  # a[i] 为房间 i 的跃迁目标

        dis = [INF] * (n + 1)
        dis[1] = 0
        dq = deque([1])

        while dq:
            x = dq.popleft()
            # 跃迁，花费 0 体力
            y = a[x]
            if dis[y] > dis[x]:
                dis[y] = dis[x]
                dq.appendleft(y)
            # 向右步行，花费 1 体力
            if x < n and dis[x + 1] > dis[x] + 1:
                dis[x + 1] = dis[x] + 1
                dq.append(x + 1)
        out_lines.append(str(dis[n]))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

